if(!exists('build_retail_sme_features'))library(creditratingsystem)
p<-system.file('extdata','retail_owner_journey.json',package='creditratingsystem');if(!nzchar(p))p<-'creditratingsystem-r/inst/extdata/retail_owner_journey.json';data<-jsonlite::read_json(p,simplifyVector=FALSE);case<-data$products[['RETAIL_SMALL_BUSINESS_FINANCE']];row<-case$owner_business_inputs[[1]]
graph<-do.call(build_customer_household_graph,row$household_graph);ob<-do.call(aggregate_household_obligations,c(row$household_obligations,list(household_graph=graph)));features<-do.call(build_retail_sme_features,c(row$features,list(household_obligations=ob)))$value;stopifnot(features$owner_draw_business_outflows==400,features$matched_owner_draw_household_inflows==400,features$cash_after_business_debt==800,row$other_household_income==800)
x<-case$lifecycle;pv<-discount_recoveries(x$cashflows,x$discount_curve,x$fx_contract,default_date='2025-01-20',evaluation_cutoff=data$evaluation_cutoff,reporting_currency='EUR');loss<-workout_lgd(1000,pv,episode_status='CLOSED',default_date='2025-01-20',evaluation_cutoff=data$evaluation_cutoff,currency='EUR')$value;stopifnot(loss$economic_loss==400,loss$economic_lgd==.4)
tr<-x$prior_lgd;fit<-fit_fractional_lgd(matrix(numeric(),nrow=3,ncol=0),unlist(tr$values),feature_order=character(),link='logit',covariance='HC0',target=tr$target,training=tr$training,model_id='native-owner-prior',model_version='1');lgd<-predict_lgd(fit,matrix(numeric(),nrow=1,ncol=0),feature_order=character(),expected_target=tr$target,default_condition='given_default')$value$mean_lgd[[1]];stopifnot(abs(lgd-.4)<1e-12,abs(fit$model$parameters$coefficients[[1]]-log(2/3))<1e-12)
bad<-row$features;bad$owner_drawings[[1]]$household_amount<-401;stopifnot(inherits(try(do.call(build_retail_sme_features,c(bad,list(household_obligations=ob))),silent=TRUE),'try-error'))
